page('Continue building AMANI.',p('Developer handoff, completion roadmap and live deployment plan.')+'<div class="accent"></div>'+h('Project links')+p(a(repo,'GitHub: skylarart1720-bot/AMANI'))+p(a(rail,'Railway project and selected environment'))+p(a('https://amani-navy.vercel.app/','Public website: amani-navy.vercel.app'))+p(a('https://amani-hck2.vercel.app/','Moderator website: amani-hck2.vercel.app'))+note('The Railway link is a hosting control panel, not an API origin. Copy the public HTTPS API origin from the orchestrator networking settings.')+h('Prepared 3 October 2026')+p('Reviewed against local HEAD feb2462 and the original 14-page blueprint. This document covers implemented features, outstanding work, implementation methods, 13 development prompts, deployment, acceptance and operations.')+p('No production credentials or conversations are included. Railway account settings and current hosted/provider state were unavailable for inspection. Website links come from existing project documentation and remain unverified live.')+h('Sharing')+p('Send this PDF to the developer. Editable HTML and a generation script accompany it. Application code and runtime data were preserved.'))
page('Executive assessment and contents.',p('The project has a substantial application foundation: two Next.js frontends, encrypted support sessions, a human-support queue, editable referrals and knowledge, URL reputation checks and a signed WhatsApp gateway. A complete public service still needs trusted content, individual staff access, live integrations, trained coverage and production verification.')+note('The website uses support.py and support.db. Older main.py ingestion/retrieval and optional PostgreSQL capabilities are not the public support pipeline. DATABASE_URL alone does not migrate live support storage or enable its vector retrieval.')+table(['Pages','Subject'],[['3–7','Purpose, architecture, source map, implemented features and gaps'],['8–11','Roadmap, local setup, API and data lifecycle'],['12–16','Environment settings, Railway/Vercel deployment and providers'],['17–19','Release verification, operations and troubleshooting'],['20–25','13 copyable feature implementation prompts'],['26','Access transfer, completion criteria and references']])+h('Review evidence')+ul(['Local HEAD feb2462: Add Vercel project configuration and deployment guide. Previous commit 0298c57: Initial AMANI application with support and moderator workflows. Remote matches the supplied repo.', '48 backend tests passed during this handoff; six deprecation warnings; 18.99 seconds. Frontend builds and live integrations were not rerun.', 'Existing user-guide assets/scripts were untracked at review time. No applicable AGENTS.md or tracked GitHub Actions workflow was found.', 'Railway service settings, volume mounts, domains and deployed SHAs were not inspected. GitHub/public pages could not be fetched through the web reader.']))
page('Purpose and intended users.',p('AMANI is a Ghana-first rights, safety and wellbeing information/referral service. Visitors should reach credible information and routes to accountable human help without registering or supplying identity details.')+table(['Pillar','Intended outcome'],[['Protest rights & civic freedom','Rights information and independent legal aid'],['Activism & youth movements','Civil-society resources and networks'],['Mental health & wellbeing','Calm support, crisis resources and professional referrals'],['Climate & environmental justice','Environmental rights and reporting pathways'],['Digital rights & online safety','Reputation checks and cyber-incident referrals'],['Youth governance participation','Civic information and participation resources'],['Human rights defenders','Protection and security support'],['Gender & intersectional justice','GBV, discrimination and witchcraft-accusation support'],['Men’s Circle','Non-judgemental counselling and peer support']])+h('Service boundaries')+p('AMANI does not guarantee emergency intervention, legal representation, treatment, partnership acceptance or immediate human response. A directory and queue do not establish a staffed service.')+h('Completion has two layers')+p('Launch readiness means all advertised channels are dependable, private, reviewed and staffed. Full blueprint delivery additionally includes Ghanaian languages, scheduled reviewed knowledge, aggregate reports, richer referrals, consented follow-up and later SMS/USSD. Agree these milestones separately.')+p('Witchcraft-accusation work crosses multiple pillars: approved content and actual referrals are needed, not only a topic description.'))
page('Architecture and hosting model.','<div class="diagram">'+''.join('<div>'+x+'</div>' for x in ['Visitor → public Next.js /api proxy','Moderator → moderator Next.js /api proxy','↓ HTTPS orchestrator origin','FastAPI main.py installs support.py','Sessions · triage · knowledge · referrals · queue · SSE','↙ support.db &nbsp; ↓ AI provider &nbsp; ↘ private URL scanner','WhatsApp ↔ Meta ↔ HTTPS gateway /webhook','Encrypted whatsapp.db → single worker → same support API'])+'</div>'+h('Single-node baseline')+p('Use one orchestrator instance, one Uvicorn worker and one mounted SQLite volume. Scanner stays internal. Gateway needs persistent storage and one worker. Vercel hosts frontends; its server proxy needs an externally reachable HTTPS API because it cannot access Railway private hostnames.')+h('Realtime and scale')+p('Visitor/moderator SSE checks changes once per second. Clients reconnect and poll as fallback. Validate hosted buffering and duration limits. Do not enable replicas or multiple gateway workers until storage, job coordination and limits are shared.')+h('Privacy')+p('Fernet encrypts stored message content; visitor capability tokens are hashed. The server and authorised staff can read chats. Web chat is not end-to-end encrypted against AMANI. Staff currently share a bearer token via a secure HTTP-only dashboard cookie.'))
page('Repository map.',table(['Path','Responsibility'],[['apps/web/app/page.tsx','Chat, handoff, topics, referrals, scanner and privacy'],['apps/web/app/localization.tsx','English/French strings'],['apps/web/app/api/[...path]/route.ts','Allowlisted public proxy'],['apps/moderator-dashboard/app/page.tsx','Login, queue, replies, directory/knowledge editing'],['apps/moderator-dashboard/app/api/[...path]/route.ts','Cookie auth and admin proxy'],['apps/orchestrator/src/support.py','Active encrypted support/admin workflow'],['apps/orchestrator/src/main.py','FastAPI app and legacy knowledge/data/PostgreSQL'],['apps/orchestrator/src/approved_source_connector.py','Legacy source collection; not scheduled public-content ingestion'],['services/url-safety/src/main.py','Reputation lookup and scans'],['apps/whatsapp-gateway/src/main.py','Signed webhook, encrypted inbox, retry worker'],['packages/shared/src/index.ts','Shared types; check against active API'],['docker-compose.yml / Dockerfiles','Container wiring and volumes'],['scripts/ and service tests/','Launcher, browser/integration/regression checks']])+h('Read order')+p('README.md → PRODUCTION.md → VERCEL.md → support.py → frontend proxies/pages → gateway/scanner → tests → blueprint_text.txt. Preserve /support and /admin contracts; legacy /chat is not interchangeable.'))
page('Implemented features and evidence.',table(['Feature','Source-backed behaviour'],[['Visitor UI','Responsive nine-topic interface; English/French; no registration'],['Sessions/privacy','Random capability, hashed token, encrypted messages, seven-day expiry, delete and quick exit'],['AI','Explicit consent, recent context, provider integration and labelled directory fallback'],['Content','Persisted editable referrals; pending/published/rejected knowledge selected by topic'],['Urgent routing','Bilingual rules before AI; crisis resource and critical case'],['Human help','Queue/transcript/replies; queued/in_progress/resolved'],['Realtime','Visitor/admin SSE with reconnect/poll fallback'],['Staff access','Shared token; HTTP-only same-site one-hour cookie'],['URL reputation','Safe Browsing/VirusTotal; consent; fresh/pending scan; unknown on failure'],['WhatsApp intake','Verify token, raw-body HMAC, destination validation, encrypted inbox and duplicate suppression'],['WhatsApp commands','human, updates, enable ai, disable ai, forget; text/retry delivery']])+h('Verification')+p('Current rerun: 48 backend tests passed. Existing VERIFICATION.md records earlier builds, browser checks at eight widths, local SSE, origin/login regressions and VirusTotal results. Historical records are not hosted verification.')+note('Implemented, configured and verified live are distinct. Key presence does not prove credit; a queue does not prove staffing; a seed contact does not prove partnership. Quick-exit deletion can fail during connectivity loss.'))
page('Remaining work and priorities.',table(['Gap','Recommended completion'],[['P0 · Staff identity','Individual accounts, MFA, roles, revocation and actor/resource audits before multi-staff real data'],['P0 · Trusted content','Review all nine pillars, emergency contacts, translations and availability'],['P0 · Production operations','HTTPS/persistent disks, funded providers, trained coverage, alerts, backup/restore proof'],['P1 · AI grounding/triage','Relevant retrieval, provenance, structured validation and expert safety evaluation'],['P1 · Knowledge pipeline','Unify public/legacy stores, scheduled allowlisted ingestion, revisions, review and freshness'],['P1 · WhatsApp','Proactive human replies, receipts, consented templates, topic menu and language'],['P1 · Referrals','Optional region, coverage/language, trust tiers, evidence/review dates'],['P1 · Languages/reports','Twi/Ga/Ewe/Hausa with professional review; aggregate outcomes and feedback'],['P2 · Scaling','Active support PostgreSQL migration, shared broker/outbox, distributed limits'],['P2 · Later scope','SMS/USSD; phone/screenshot-text scams; local registry; consented incident reporting']])+p('Source does not establish formal NGO partnerships, independent security/privacy review, certified accessibility, source freshness SLA or web E2EE. No proactive WhatsApp human delivery, Ghanaian languages, aggregate dashboard or consented case-worker contact workflow is demonstrated.')+note('Agree public pilot scope with the owner. Do not advertise later blueprint features before delivery. Professional/legal/clinical sign-off is a delivery task, not an automated feature.'))
page('Milestones and work packages.',table(['Milestone','Exit evidence'],[['M0 · Reproduce','Fresh installs, both builds, current tests, synthetic local handoff, recorded SHA/dependencies'],['M1 · Live staging','Railway services/volumes, two Vercel projects, provider checks, restart persistence'],['M2 · Trust/operations','Staff identity/audits, reviewed content, verified referrals, trained escalation drill'],['M3 · Complete channels','Grounded knowledge, reliable WhatsApp human replies, regional matching, hosted outage/reconnect tests'],['M4 · Inclusion/reporting','Reviewed Ghanaian languages, analytics/feedback, accessibility/low-bandwidth evaluation'],['M5 · Scale/expand','Shared PostgreSQL/jobs/limits, load evidence, SMS/USSD and partners']])+h('First assignments')+ol(['Developer: reproduce baseline and inventory actual Railway/Vercel settings without touching real data.', 'Developer + operations: staging, identity, alerts, WhatsApp outbound and restore tooling.', 'Editorial/legal/clinical reviewers: approved content, emergency resources, referral verification and safeguarding.', 'Developer + reviewers: ingestion/retrieval, language coverage and evaluations.', 'Owner: pilot hours, incident ownership, scope exclusions and service measures.'])+p('Estimate after access/content availability is known. Meta onboarding and professional reviews can dominate delivery. Do not inherit original blueprint week ranges as promises.')+p('Use small reviewed PRs, protected branches and staging. Each package includes tests, acceptance evidence and migration/rollback where applicable.'))
page('Local developer setup.',h('Fresh Windows checkout')+code('git clone https://github.com/skylarart1720-bot/AMANI.git\ncd AMANI\npy -3.12 -m venv .venv\n.\\.venv\\Scripts\\python.exe -m pip install -r apps/orchestrator/requirements.txt -r services/url-safety/requirements.txt -r apps/whatsapp-gateway/requirements.txt\n.\\.venv\\Scripts\\python.exe -m pip install -r scripts/test_requirements.txt\nnpm.cmd --prefix apps/web ci\nnpm.cmd --prefix apps/moderator-dashboard ci\nCopy-Item .env.example .env\nnpm.cmd run build\n.\\.venv\\Scripts\\python.exe scripts\\run_local.py')+p('Copy .env only in a fresh checkout and populate privately. Use a supported Node release compatible with locked Next.js and pin it in CI. Containers use Python 3.12; earlier Windows verification used 3.11. Launcher prints actual free ports.')+table(['Default address','Purpose'],[['127.0.0.1:3000','Web'],['127.0.0.1:3100','Moderator'],['127.0.0.1:8100','API'],['127.0.0.1:8200','Scanner'],['127.0.0.1:8300/webhook','Local WhatsApp; not accessible to Meta']])+p('Login uses ADMIN_API_TOKEN or generated data/.admin-token; key in data/.chat-key. Do not transfer these. Process records/logs: .runtime/. Stop with scripts/stop-local.ps1.')+note('Launcher is Windows-oriented. On Linux/macOS use python3/.venv/bin/python for tests; Compose is the portable stack starting point.'))
page('API and proxy contract.',p('Browsers call same-origin /api/...; Next.js strips /api before forwarding. Visitor routes use the random bearer capability. Admin routes require staff bearer auth.')+table(['FastAPI route','Method / function'],[['/health','GET · process health, not provider readiness'],['/support/status','GET · configured flags and limits'],['/support/directory','GET · topics/referrals'],['/support/sessions','POST create; DELETE with visitor token'],['/support/messages /support/events','GET transcript/case or SSE; visitor token'],['/support/chat','POST message, topic?, ai_consent, language en/fr'],['/support/handoff','POST human-help request; visitor token'],['/support/check-link','POST URL request with consent'],['/admin/queue /admin/events','GET staff queue/SSE'],['/admin/queue/{case_id}','PATCH queued/in_progress/resolved'],['/admin/queue/{case_id}/reply','POST human reply'],['/admin/directory','GET/PUT list/upsert'],['/admin/knowledge','GET/POST list/pending entry'],['/admin/knowledge/{id}','PATCH published/rejected']])+h('Dashboard auth')+p('POST /api/login trims token whitespace, checks /admin/queue and sets amani-admin; /api/logout clears it. Proxy forwards cookie token server-side. Vercel does not need ADMIN_API_TOKEN.')+p('Chat/reply maximum: 4,000 characters. Preserve modes directory, ai, urgent and human. Origin check compares browser Origin with Host: diagnose proxy/domain mismatch rather than disabling it.')+p('Shared types in packages/shared need alignment as fields evolve. Keep backward-compatible response shapes for both web and gateway.'))
page('Storage, retention and migration.',table(['Store','Meaning'],[['support.db','Active sessions/messages/cases/audit/directory/knowledge'],['whatsapp.db','Encrypted inbox/session token, HMAC sender lookup, retries'],['amani_line.db / legacy PostgreSQL','Older chats/knowledge/vector capabilities; legacy chat may be plaintext']])+h('Lifecycle')+p('Sessions expire seven days from creation; hourly/request-time cleanup. Messages/cases cascade on delete; audit retention up to 90 days. Gateway inbox/sender retention seven days; sent payloads cleared. Backups/provider/device records need separate policy.')+h('Secrets')+p('Keep CHAT_ENCRYPTION_KEY stable and recoverable separately. Replacement without decrypt/re-encrypt migration breaks ciphertext. Add key IDs and tested rotation before changing it. Staff token is read at import: restart/redeploy for rotation.')+h('PostgreSQL upgrade')+ol(['Introduce support-store abstraction behind active routes, preserving tokens/encryption/deletion/API semantics.', 'Create versioned schemas/indexes for support/gateway/outbox. DATABASE_URL alone is insufficient.', 'Migrate authorised snapshot; verify counts, transcripts, ciphertext and case links.', 'Pause writes for cutover; retain compatible rollback/key; test expiry/delete/reconnect.', 'Add shared jobs/limits and concurrency evidence before multiple replicas/workers.'])+note('Use fresh staging data. Do not upload local data/ wholesale. AMANI deletion cannot erase Meta/device or unmanaged backup copies; document these limits accurately.'))
page('Environment configuration.',table(['Variable','Service / setting'],[['APP_ENV','API/scanner: production'],['PROJECT_ROOT','Python containers: /app'],['AMANI_DATA_DIR','API/gateway: /data with persistent mount; never blank'],['CHAT_ENCRYPTION_KEY','API/gateway: stable Fernet secret'],['ADMIN_API_TOKEN','API only: fresh high-entropy staff token'],['URL_SAFETY_URL','API: actual private scanner origin incl. 8001'],['OPENAI_API_KEY / MODEL','API: funded key and supported model; verify source default gpt-4o-mini'],['OPENAI_BASE_URL','API: https://api.openai.com/v1 unless approved override'],['ORCHESTRATOR_URL','Web/admin: public HTTPS API; gateway: private API'],['COOKIE_SECURE','Moderator app: true'],['SAFE_BROWSING_API_KEY / VIRUSTOTAL_API_KEY','Scanner: permitted-use credentials/quota'],['WHATSAPP_PROVIDER','Gateway: meta only after onboarding'],['META_WHATSAPP_TOKEN / PHONE_NUMBER_ID','Gateway: approved access credential and provisioned number ID'],['META_WEBHOOK_VERIFY_TOKEN / APP_SECRET','Gateway: challenge token and raw-body HMAC secret'],['META_WHATSAPP_API_VERSION','Gateway: supported version from Meta app dashboard']])+h('Generate secrets privately')+code('.\\.venv\\Scripts\\python.exe -c "import secrets; print(secrets.token_urlsafe(32))"\n.\\.venv\\Scripts\\python.exe -c "from cryptography.fernet import Fernet; print(Fernet.generate_key().decode())"')+p('First output: staff token. Second: Fernet key. Transfer through secret settings, never documents/tickets/repo. Keep staging/production separate.')+note('No NEXT_PUBLIC_* secrets/API origin. Gateway default API port is 8005; Docker API uses 8000. Always explicitly configure ORCHESTRATOR_URL.'))
page('Railway deployment runbook.',p('Open '+a(rail,'the provided environment')+'. Inventory existing services, source SHA/branch, root, health, domain and mount first; reuse correct services.')+table(['Service','Root / Dockerfile / fixed port'],[['orchestrator','apps/orchestrator · Dockerfile · 8000'],['url-safety','services/url-safety · Dockerfile · 8001'],['whatsapp-gateway','apps/whatsapp-gateway · Dockerfile · 3001']])+ol(['Connect repo/branch. Set each Root Directory to the service directory: COPY paths assume this context. Confirm Docker detection.', 'Scanner: provider settings + APP_ENV=production; /health; private only.', 'API: persistent /data; page 12 variables; actual scanner private origin incl. 8001; one replica/Uvicorn worker.', 'Health /health; align Railway PORT/target with Docker 8000. Generate public HTTPS API domain for Vercel server proxy.', 'Gateway: separate persistent /data volume; Meta settings/key; private API origin incl. 8000; one worker/replica; HTTPS target 3001.', 'Deploy scanner→API→gateway; synthetic tests prove internal connectivity and external HTTPS.', 'Restart/redeploy API/gateway and prove persistence; record real API/webhook URLs.'])+p('Railway does not automatically share Compose support-data. Gateway needs whatsapp.db on its own disk and explicit key; it calls support API, not support.db.')+p('Use assigned private hostnames. If IPv6 DNS cannot reach supplied 0.0.0.0 bind, adjust IPv6-capable binding according to platform guidance and test. Keep scanner/disks private.')+p('Official references: '+a('https://docs.railway.com/builds/dockerfiles','Dockerfiles')+' · '+a('https://docs.railway.com/volumes','Volumes')+' · '+a('https://docs.railway.com/networking/private-networking','Private networking')+' · '+a('https://docs.railway.com/deployments/healthchecks','Healthchecks')+'.'))
page('Vercel deployment runbook.',p('Import repository twice or inspect existing projects. Existing guide URLs: amani-navy.vercel.app and amani-hck2.vercel.app; confirm ownership/SHA and live behaviour.')+table(['Setting','Public','Moderator'],[['Root','apps/web','apps/moderator-dashboard'],['Framework','Next.js','Next.js'],['Install / build','npm ci / npm run build','npm ci / npm run build'],['Output','Framework default','Framework default'],['ORCHESTRATOR_URL','Railway public HTTPS API','Same API'],['COOKIE_SECURE','Not needed','true']])+ol(['Set Preview/Production independently. Localhost and Railway dashboard link are invalid API origins.', 'Deploy web; /api/support/status must return backend JSON; send fictional chat.', 'Deploy moderator; enter current backend token and verify queue/reply. No ADMIN_API_TOKEN variable needed in Vercel.', 'Verify same-origin mutations, secure cookie, invalid token and logout; check Host/Origin on custom domains.', 'Interrupt SSE and test host duration limits; polling/reconnect must deliver human replies.', 'Configure owned domains/HTTPS; restrict moderator/demo access and verify protection on exact shared URL.', 'Redeploy after settings changes; record URLs and frontend/backend SHAs.'])+h('Alternative host')+p('docker compose up --build -d supplies portable baseline. Use HTTPS reverse proxy before loopback web/admin/webhook ports; keep API/scanner internal, persist support-data, validate containers/streaming/backups. Vercel does not run Compose.')+p('References: '+a('https://vercel.com/docs/monorepos','Vercel monorepos')+' · '+a('https://vercel.com/docs/deployment-protection','Deployment protection')+'.'))
page('Activate AI and URL reputation.',h('AI')+ol(['Assign budget/account owner, fund provider and configure key/model/base URL on API.', 'Restart/redeploy; run scripts/check_integrations.py. ai_configured only means key presence.', 'Fictional hosted consent-on message must return mode=ai; consent off must make zero model calls.', 'Test quota/key/timeout fallback and urgent bypass; set budget/error alerts without transcript logging.'])+p('Historical verification reports 429 credit_balance_exhausted. This is not a current balance check; retest actual provider.')+h('Scanner')+ol(['Configure approved provider(s), private scanner URL and /health connectivity.', 'Test consent, current/missing/stale report, fresh/pending/completed scan and provider failures using mocks/sanctioned URLs.', 'Preserve unknown on missing evidence; no_known_threats is not guaranteed safety.', 'Explain VirusTotal exposure of private URL tokens; pending jobs in process memory can be lost on restart.'])+p('Scanner never visits submitted URL. Private/local inputs are rejected. Phone/screenshot-text scams, local campaigns and consented CSA reporting remain separate work.')+p('References: '+a('https://developers.google.com/safe-browsing/v4/lookup-api','Safe Browsing')+' · '+a('https://docs.virustotal.com/reference/scan-url','VirusTotal scan')+' · '+a('https://docs.virustotal.com/reference/url','URL reports')+'. Check actual quotas/terms.'))
page('Activate WhatsApp and human handoff.',ol(['Complete Meta business/app/number onboarding, production permissions, token owner/rotation and supported Graph version.', 'Gateway persistent disk/one worker; /health configured=true; private API reachable.', 'Register https://ACTUAL-GATEWAY-DOMAIN/webhook and matching verify token; subscribe to messages.', 'Correct GET challenge succeeds; invalid HMAC/wrong destination POST fails.', 'Authorised test phone: fictional text, welcome, consent off; test enable ai/disable ai/human/updates/forget.', 'Replay inbound ID; mock delivery interruption/retry/terminal failure and confirm operator visibility.', 'Before complete WhatsApp launch add proactive moderator outbox, status receipts, permitted templates, menu and languages.'])+h('Current limitations')+p('Human replies are pulled with updates. No proactive template flow or interactive nine-topic menu. Gateway defaults to English. Delivery is at least once; a timeout after accepted send may duplicate a retry. Saved answer reduces repeated processing but support effects need stronger idempotency.')+h('Provider policy and privacy')+p('Verify current customer-service window, template categories, fees and opt-in rules directly with Meta. Do not hardcode remembered policy. Meta sees phone number; AMANI encrypts payloads and hashes sender lookups. forget cannot delete Meta/device messages.')+p('Test expired sessions consistently for commands and chat. Failed jobs, invalid tokens and callback status need operational alert/retry controls.')+p(a('https://developers.facebook.com/docs/whatsapp/cloud-api/overview','Meta Cloud API overview')+' is the starting reference; fetch failed during review, so production account details require verification.'))
page('Acceptance and launch gates.',h('Repeatable checks')+code('npm.cmd run build\n.\\.venv\\Scripts\\python.exe -m pytest apps/orchestrator/tests services/url-safety/tests apps/whatsapp-gateway/tests -q\n.\\.venv\\Scripts\\python.exe scripts\\check_integrations.py\n.\\.venv\\Scripts\\python.exe scripts\\browser_check.py\n.\\.venv\\Scripts\\python.exe scripts\\origin_check.py\n.\\.venv\\Scripts\\python.exe scripts\\realtime_check.py\n.\\.venv\\Scripts\\python.exe scripts\\check_moderator_login.py')+p('Current rerun: 48 passed, six warnings, 18.99s. Builds/provider/browser checks were not rerun. Local scripts require running services; parameterise staging before hosted acceptance. Never use production fixtures.')+h('Hosted acceptance')+ul(['Visitor isolation; expiry/delete cascades and active stream updates.', 'Consent-off zero model calls; funded AI/fallback and urgent bypass.', 'Request/queue/staff reply/visitor response/resolution; auth/logout/revocation.', 'Pending/withdrawn content excluded; honest referral verification.', 'English/French/mobile/keyboard/screen reader/low bandwidth/quick exit.', 'URL consent/pending/unknown; WhatsApp signature/dedup/retry/forget.', 'Persistence after restart; backup restore; timeout/reconnect; abuse/outage.'])+note('Block launch for unverified emergency contacts, advertised unstaffed support, lost keys/data, unauthorised access, failing deletion or fabricated safety. Obtain content/safeguarding/privacy/security review.'))
page('Operations and rollback.',h('Owners and staffing')+p('Name deployment, incident, privacy, content and safeguarding owners. Publish true hours/response limits. Confirm referral numbers/hours/languages directly; agree escalation contacts. Train staff and run synthetic urgent drills.')+h('Monitoring')+p('Alert on uptime, API/provider errors, queue/critical age, failed WhatsApp jobs, disk and spend. Redact content/phone numbers. Safe retry/acknowledgement and editorial freshness tasks need operator ownership.')+h('Backup and recovery')+p('Use consistent SQLite backup, not live file copies. Protect support.db/whatsapp.db and keys separately. Set retention/access/recovery targets; isolated restore must prove ciphertext, cases and gateway state. Retain deletion obligations when restoring old data.')+h('Release sequence')+ol(['Record tested SHA/schema versions; recoverable pre-migration snapshot.', 'Compatible API first, frontends next; synthetic smoke immediately.', 'On failure restrict affected flow and redeploy last compatible version.', 'Do not run old code over incompatible schema. Reviewed recovery and deletion tombstones prevent resurrecting erased chats.'])+h('Cost and capacity')+p('Budget hosting, persistent services/disks/backups, AI tokens, WhatsApp fees, monitoring and staffing. Obtain account prices and measure usage; no total is implied without traffic/staff assumptions.')+note('Content refresh, updates, staff supervision and drills continue after launch.'))
page('Troubleshooting and review risks.',table(['Symptom','Action'],[['API 503','Check actual origin, backend, DNS/HTTPS/timeouts; redacted logs'],['Startup fails','Validate production token/Fernet key and writable /data'],['Data lost','Verify persistent volume and AMANI_DATA_DIR'],['Shared 429','Trusted proxy attribution and shared rate limits'],['Login failure','Current token, API, cookie; do not print secrets'],['Mutation 403','Host/Origin domain mismatch; preserve checks'],['SSE stalls','Buffering/time limits; prove reconnect/polling'],['AI unavailable','Key/model/quota/provider; safe health categories'],['Scanner unknown','Missing evidence/provider failure/lost job; preserve uncertainty'],['WhatsApp silent/duplicate','API/settings/jobs/policy; outbox/receipt reconciliation']])+h('Hardening targets')+p('API reads body before size check: add bounded receive and edge limits. Audit stream/transcript access with actor/resource/outcome. Test ambiguous topics; grounding/output validation must extend beyond prompts.')+p('No tracked CI found. Verify next lint tooling. Historical backend dependency audit incomplete. Six current test warnings concern lifecycle/dependency deprecations; plan deliberate maintenance.')+p('Next.js origin checks do not alone secure the externally reachable API. Review edge abuse/session/provider quota protection.'))
base='Work in AMANI. Read README.md, PRODUCTION.md, VERCEL.md, blueprint, support.py and proxies. Extend active /support and /admin, not silently legacy /chat. Preserve anonymity, consent, deletion and conservative failures. Use synthetic fixtures and redact secrets/content. Deliver code, migrations, tests, updated config/docs and acceptance evidence.'
def prompt(t,task,accept,files): return h(t)+p('<b>Copyable brief:</b> '+task)+p('<b>Acceptance:</b> '+accept)+p('<b>Start:</b> '+files)
page('Prompts: identity and audits.',note('Prefix any brief on pages 20–25 with this shared block.')+p(base)+prompt('A · Individual staff identity','Replace shared token with approved OIDC accounts, moderator/editor/reviewer/admin roles, MFA, expiry/logout and immediate revocation. Enforce API/proxy/SSE permissions. Controlled time-limited migration; secrets server-side.','Wrong-role access fails; revoked staff lose REST/stream access; reviewer-only publication; hosted login/logout passes.','support.py; moderator page/proxy.')+prompt('B · Attributable audits','Record actor/action/object/time/outcome for transcript/stream reads, replies, case/referral edits and reviews. Exclude raw text/tokens/phones. Authorised search, integrity and retention.','Distinct staff attributable; failed access safely recorded; retention works; staff cannot edit audits.','support.py audit/admin; dashboard.'))
page('Prompts: knowledge and safe AI.',prompt('C · Reviewed-content pipeline','Unify legacy/public knowledge. Scheduled allowlisted ingestion, revision hashes, metadata, reviewer identity, publication/withdrawal/freshness. Bound fetches and prevent private/local/redirect SSRF. New revisions remain pending.','Pending/withdrawn excluded; idempotent ingestion; provenance/reviewer and revisions; stale flags/retries.','main.py; approved_source_connector.py; support.py; knowledge UI.')+prompt('D · Grounded retrieval and triage','Replace three topic-only entries with relevant published retrieval using language/optional region. Version prompt; structured claims/cited entry/referral IDs/outcome; validate provenance and support. Preserve urgent rules before AI; expert bilingual/adversarial evaluation.','No invented facts/contacts/citations; no consent means no calls; withdrawal immediate; urgent bypass; missing evidence fallback; expert false-negative review.','support retrieval/ai_reply/chat; tests; visitor UI.')+note('Vector search does not itself prove accuracy; reviewed evidence and measured grounding remain required.'))
page('Prompts: WhatsApp completion.',prompt('E · Proactive human delivery','Durable outbox on WhatsApp case replies; encrypted destination mapping, opt-in and last inbound time. Permitted session/approved template sending under current Meta rules. Provider IDs/status callbacks/backoff/failed jobs/operator retry. Idempotent support effects and ambiguous-send reconciliation.','Reply without updates; forget/opt-out blocks sends; no duplicate effects; failure alerts; outside-window policy reviewed.','gateway; human_reply; outbox; delivery UI.')+prompt('F · Menu/language/expiry','Interactive nine-topic menu, language/human/emergency/consent/delete. Short-lived preferences passed to API. Consistent expired-session recovery for human/updates/chat.','Correct topic/language; AI initially off; command recovery; sender/session/outbox deletion; accurate Meta disclosure.','gateway process/webhook; MessageInput; localisation/tests.')+note('One worker until shared locks/storage. Use mocked errors and approved test phones. Do not promise exactly-once delivery without proof.'))
page('Prompts: referrals and inclusion.',prompt('G · Verified regional referrals','Add coverage/contact channels/hours/languages/trust tiers/evidence/review date. Optional coarse region in chat/directory; no precise location. Reviewer workflow and stale/unverified labels; emergency resources separate.','Region/language matches; no falsely confirmed stale contacts; no exact-location requirement; audit provenance.','DirectoryInput/get_directory/chat; both UIs/shared types.')+prompt('H · Languages and accessibility','Twi/Ga/Ewe/Hausa catalogue with professional safety/legal review. Explicit untranslated fallback; align WhatsApp/web. Keyboard/focus/screen reader/contrast/zoom/low bandwidth/quick exit evaluation against WCAG 2.2 AA.','Translated navigation/consent/errors; approved urgent templates; fallback disclosed; keyboard handoff/delete; mobile/screen-reader evidence.','localization.tsx; page/styles; gateway/content.')+p('Human messages/source documents are not professionally translated automatically. Consented follow-up needs a separate optional purpose/contact flow with encrypted storage, access controls and deletion.'))
page('Prompts: operations and reporting.',prompt('I · Availability and alerts','Hours/availability, assignment/acknowledgement, urgent alerts/escalation timers. Approved channel without transcripts/identifiers; honest visitor delays. Failed-job/outage view, controlled audited retry and runbook.','Critical reaches on-call; unacknowledged escalates; true after-hours copy; no emergency promise; safe retry.','queue/admin; gateway worker; settings.')+prompt('J · Aggregate metrics/feedback','Coarse topic/channel/outcome, queue waits/provider errors/referral clicks and optional short satisfaction. Approved retention/small-count suppression; no raw chats/session hashes/phones. Authorised reports/metric definitions.','Synthetic counts reconcile; small cohorts suppressed; privacy/retention documented; no ad trackers.','support outcomes/events; feedback/report UI.')+p('Partner agreements, professional review and trained staffing need accountable owners. Engineering implements workflows but cannot establish real-world coverage or partnerships.'))
page('Prompts: infrastructure and expansion.',prompt('K · CI and staging proof','GitHub Actions npm ci/lint/types/builds/Python tests/audits. Build Python containers with synthetic production startup smoke. Hosted harness with URLs/temporary credentials; checks before promotion, redacted logs.','Fresh runner passes; images start; failure blocks; hosted auth/delete/handoff/reconnect/persistence; no real fixtures.','scripts/packages/Dockerfiles; .github/workflows.')+prompt('L · Shared storage/scale','Active support/gateway PostgreSQL, migrations, outbox/broker/distributed limits. Preserve encryption/capabilities; worker locks/idempotency/trusted proxy attribution; staged cutover/rollback.','Shared sessions/cases across replicas; no races; expiry/delete; restore rehearsed; fair limits.','support.py; gateway; migrations/config.')+prompt('M · Later channels/scams','Owner-approved SMS/USSD with signed callbacks, menus/privacy/consent/shared API. Separately evidence-based phone/screenshot-text checks, scam registry and explicit-consent reporting; no external messages without approved integration.','Provider menu/handoff/delete; SMS limits disclosed; evidence supports verdict; reporting opt-in.','New adapter; scanner/UI/provider tests.'))
page('Access transfer and completion.',h('Invite the developer')+ul(['GitHub role, protected branches, PR review and issue backlog.', 'Railway project/environment; both Vercel projects; owned domain/DNS.', 'Scoped provider/Meta accounts through invitations/secret manager, not PDF keys.', 'Blueprint, PDF, existing guide, reviewed content/partner/staff contacts and incident plan.', 'Inventory web/admin/API/webhook URLs, roots/ports/volumes, SHAs and owners.'])+h('Definition of complete')+p('All advertised features pass hosted acceptance; reviewed knowledge and emergency referrals cover nine pillars; trained staff cover promised hours; deletion/retention/encrypted recovery work; staff access attributable; WhatsApp/provider failures handled; security/content/safeguarding sign-off. Later scope excluded until delivered.')+h('Source references')+p(' · '.join(a(repo+'/blob/main/'+f,f) for f in ['README.md','PRODUCTION.md','VERCEL.md','VERIFICATION.md','blueprint_text.txt']))+h('Official hosting references')+p(a('https://docs.railway.com/builds/dockerfiles','Railway Dockerfiles')+' · '+a('https://docs.railway.com/volumes','Volumes')+' · '+a('https://docs.railway.com/networking/private-networking','Private networking')+' · '+a('https://docs.railway.com/deployments/healthchecks','Healthchecks')+' · '+a('https://vercel.com/docs/monorepos','Vercel monorepos'))+note('Documentation only; no application deployment was changed. Verify current inventory before production changes and retain synthetic release evidence.'))
css='''@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;color:#172b24;background:#e5eae6;font:10.5pt/1.45 Arial,sans-serif}.page{position:relative;width:210mm;height:297mm;background:white;padding:15mm 17mm 18mm;break-after:page;overflow:hidden}header{display:flex;justify-content:space-between;padding-bottom:10px;margin-bottom:20px;border-bottom:2px solid #185347}header b{font-size:20pt;color:#185347}header span{display:block;font-size:7pt;letter-spacing:1.5px}header small{font-size:7pt;color:#687a6e}h1{font-size:26pt;line-height:1.12;color:#185347;margin:9px 0 19px}h2{font-size:12pt;color:#185347;margin:18px 0 7px}p{margin:8px 0 12px}li{margin:7px 0}ul,ol{padding-left:20px}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:9pt;margin:12px 0}th{background:#185347;color:white;text-align:left;padding:8px}td{padding:7px 8px;vertical-align:top;border-bottom:1px solid #dce6df;overflow-wrap:anywhere}td:first-child{font-weight:600}tr:nth-child(even){background:#f2f6f2}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#edf4ed;padding:12px;font:8pt/1.45 Consolas,monospace;border-left:3px solid #185347}aside{background:#fff7d6;border-left:4px solid #d6bd48;padding:12px;margin:14px 0;font-size:9.5pt}a{color:#176554;overflow-wrap:anywhere}footer{position:absolute;bottom:12mm;left:17mm;right:17mm;border-top:1px solid #d8e0d9;padding-top:8px;display:flex;justify-content:space-between;font-size:7pt;color:#6a7a6d}.diagram{background:#eef5ef;text-align:center;padding:12px}.diagram div{padding:8px;border-bottom:1px solid #d7e4da}.accent{height:5px;width:65px;background:#d6bd48;margin:25px 0}@media print{body{background:white}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}'''
sections=[]
for i,(title,body) in enumerate(pages): sections.append(f'<section class="page"><header><b>AMANI<span>RIGHTS &amp; WELLBEING</span></b><small>DEVELOPER HANDOFF / EDITION 1.0</small></header><main><h1>{title}</h1>{body}</main><footer><span>3 October 2026 · Source snapshot feb2462</span><b>{i+1:02}</b></footer></section>')
html=OUT/'AMANI_Developer_Handoff.html'; html.write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>AMANI Developer Handoff</title><style>'+css+'</style><body>'+''.join(sections)+'</body></html>',encoding='utf-8')
with sync_playwright() as pw:
    browser=pw.chromium.launch(channel='msedge',headless=True); tab=browser.new_page(viewport={'width':1000,'height':1300})
    tab.goto(html.as_uri()); tab.emulate_media(media='print')
    overflow=tab.evaluate("() => [...document.querySelectorAll('.page')].map((x,i)=>({page:i+1,bottom:x.querySelector('main').getBoundingClientRect().bottom,footer:x.querySelector('footer').getBoundingClientRect().top})).filter(x=>x.bottom>x.footer-10)")
    print('Overflow:',json.dumps(overflow))
    if overflow: raise RuntimeError('Page bounds exceeded')
    raw=OUT/'raw.pdf'; tab.pdf(path=str(raw),format='A4',print_background=True,prefer_css_page_size=True,tagged=True)
    for n in [1,4,13,20,26]: tab.locator('.page').nth(n-1).screenshot(path=str(OUT/f'preview-{n:02}.png'))
    browser.close()
reader=PdfReader(raw); assert len(reader.pages)==len(pages),(len(reader.pages),len(pages))
writer=PdfWriter(); writer.append(reader); writer.add_metadata({'/Title':'AMANI | Developer Handoff and Deployment Plan','/Author':'AMANI','/Subject':'Implementation status, feature prompts and deployment'})
for i,(title,_) in enumerate(pages): writer.add_outline_item(title,i)
pdf=OUT/'AMANI_Developer_Handoff.pdf'
with pdf.open('wb') as f: writer.write(f)
raw.unlink(); final=PdfReader(pdf); text='\n'.join(x.extract_text() or '' for x in final.pages)
for expected in ['Railway deployment runbook','WhatsApp','CHAT_ENCRYPTION_KEY','48','Prompts:']: assert expected in text,expected
annotations=sum(len(x.get('/Annots',[])) for x in final.pages); assert annotations>=20,annotations
(OUT/'test-result.json').write_text(json.dumps({'date':'2026-10-03','commit':'feb2462','backend_tests':{'passed':48,'warnings':6,'seconds':18.99},'frontend_build_rerun':False,'hosted_verification':False},indent=2))
print(f'PASS: {len(final.pages)} pages; {len(final.outline)} bookmarks; {annotations} annotations; {pdf.stat().st_size:,} bytes'); print(pdf)
